<?php use ImWiki\Security\Csrf; use ImWiki\Security\Html; use ImWiki\Support\Url; $title='Logowanie'; $passwordProviders=$passwordProviders??[['key'=>'local','name'=>'Local account','type'=>'local']]; $oidcProviders=$oidcProviders??[]; ?>
<section class="auth-wrap"><div class="card auth-card"><h1>Zaloguj się do imWiki</h1><?php if($error): ?><div class="alert danger"><?=Html::e($error)?></div><?php endif; ?><form method="post" action="<?=Html::e(Url::to('/login'))?>"><?=Csrf::field()?><?php if(count($passwordProviders)>1):?><label>Metoda logowania<select name="provider"><?php foreach($passwordProviders as $provider):?><option value="<?=Html::e($provider['key'])?>"><?=Html::e($provider['name'])?></option><?php endforeach;?></select></label><?php else:?><input type="hidden" name="provider" value="<?=Html::e($passwordProviders[0]['key']??'local')?>"><?php endif;?><label>Login lub e-mail<input name="login" autocomplete="username" required autofocus></label><label>Hasło<input name="password" type="password" autocomplete="current-password" required></label><button class="button">Zaloguj się</button></form><?php if($oidcProviders):?><div class="auth-divider"><span>lub</span></div><div class="auth-providers"><?php foreach($oidcProviders as $provider):?><a class="button secondary" href="<?=Html::e(Url::to('/auth/oidc/'.rawurlencode($provider['provider_key'])))?>">Zaloguj przez <?=Html::e($provider['display_name'])?></a><?php endforeach;?></div><?php endif;?><p><a href="<?=Html::e(Url::to('/forgot-password'))?>">Nie pamiętam hasła</a></p></div></section>
